'use strict';
(()=>{
  const perfumeUrl='/shop/?collection=perfume#collection';
  const finalImages={'Black London':'/assets/spray-products-final/black-london-new.png','Sweet Rose':'/assets/spray-products-final/sweet-rose-new.png','Velvet Night':'/assets/spray-products-final/velvet-night-new.png','Machmoun':'/assets/spray-products-final/machmoun-new.png','Cotton Candy':'/assets/spray-products-final/cotton-candy-new.png','بلاك لندن':'/assets/spray-products-final/black-london-new.png','سويت روز':'/assets/spray-products-final/sweet-rose-new.png','فيلفت نايت':'/assets/spray-products-final/velvet-night-new.png','المشموم':'/assets/spray-products-final/machmoun-new.png','كوتن كاندي':'/assets/spray-products-final/cotton-candy-new.png'};
  const style=document.createElement('style');style.textContent=`
  @media(min-width:701px){#home-products,#bakhoor-products{display:grid!important;grid-template-columns:repeat(4,minmax(0,1fr))!important;gap:38px 25px!important;max-width:none!important;margin-left:0!important;margin-right:0!important}#home-products .product-card,#bakhoor-products .product-card{min-width:0!important;width:auto!important}body.home-visual-nav header nav{display:none!important}body.home-visual-nav header{grid-template-columns:1fr auto 1fr}}
  .visual-home-menu{background:#fff;border-bottom:1px solid var(--line);padding:28px 4.5% 32px}.visual-home-menu-head{display:flex;align-items:end;justify-content:space-between;margin-bottom:18px}.visual-home-menu-head .eyebrow{margin:0}.visual-home-menu-head span{font-size:10px;letter-spacing:1.2px;color:var(--muted);text-transform:uppercase}.visual-home-menu-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.visual-menu-card{position:relative;display:block;aspect-ratio:1.18/1;overflow:hidden;background:#e9dfd0}.visual-menu-card img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;transition:transform .65s var(--ease),filter .35s ease}.visual-menu-card:after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,rgba(15,11,8,.78),rgba(15,11,8,.03) 62%)}.visual-menu-card strong{position:absolute;z-index:2;left:14px;right:14px;bottom:12px;color:#fff;font:400 18px/1.05 var(--serif);text-shadow:0 1px 8px #0008}.visual-menu-card:hover img{transform:scale(1.045);filter:brightness(1.04)}
  .perfume-collection-banners{padding-top:42px!important;padding-bottom:18px!important}.perfume-collection-banner-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.perfume-collection-banner{position:relative;display:block;overflow:hidden;aspect-ratio:3/2;background:#eee}.perfume-collection-banner img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .55s ease}.perfume-collection-banner:after{content:'';position:absolute;inset:0;background:linear-gradient(0deg,rgba(0,0,0,.58),transparent 55%)}.perfume-collection-banner span{position:absolute;z-index:2;left:20px;bottom:18px;color:#fff;font:400 27px/1 var(--serif);letter-spacing:.02em}.perfume-collection-banner:hover img{transform:scale(1.025)}
  @media(max-width:700px){#bakhoor-products{display:flex!important;gap:14px!important;overflow-x:auto!important;overflow-y:hidden!important;scroll-snap-type:x mandatory!important;-webkit-overflow-scrolling:touch!important;padding-bottom:10px!important;margin-right:-5vw!important;margin-left:-5vw!important;padding-right:5vw!important;padding-left:5vw!important;scrollbar-width:none!important}#bakhoor-products::-webkit-scrollbar{display:none!important}#bakhoor-products .product-card{flex:0 0 clamp(245px,72vw,330px)!important;scroll-snap-align:start!important;min-width:0!important}.visual-home-menu{padding:22px 0 24px}.visual-home-menu-head{padding:0 18px;margin-bottom:14px}.visual-home-menu-head span{display:none}.visual-home-menu-grid{display:flex;gap:10px;overflow-x:auto;scroll-snap-type:x mandatory;-webkit-overflow-scrolling:touch;padding:0 18px 7px;scrollbar-width:none}.visual-home-menu-grid::-webkit-scrollbar{display:none}.visual-menu-card{flex:0 0 138px;aspect-ratio:.9/1;scroll-snap-align:start}.visual-menu-card strong{font-size:17px;left:11px;right:8px;bottom:10px}.perfume-collection-banners{padding-top:26px!important}.perfume-collection-banner-grid{display:flex;overflow-x:auto;gap:12px;scroll-snap-type:x mandatory;padding-bottom:8px;scrollbar-width:none}.perfume-collection-banner-grid::-webkit-scrollbar{display:none}.perfume-collection-banner{flex:0 0 82%;scroll-snap-align:start}.perfume-collection-banner span{font-size:23px;left:15px;bottom:14px}}
  `;document.head.appendChild(style);
  const menuItems=[['Perfumes','/shop/?collection=perfume#collection','/Perfumes/ChatGPT%20Image%20Sep%2027,%202026,%2007_24_09%20AM.png'],['Luxury Spray','/room-sprays/','/room-sprays/ChatGPT%20Image%20Sep%2027,%202026,%2007_23_58%20AM.png'],['Oud & Bakhoor','/oud-bakhoor/','/oud-bakhoor/ChatGPT%20Image%20Sep%2027,%202026,%2007_23_51%20AM.png'],['Discovery Set','/products/discovery-set/','/discovery-set/ChatGPT%20Image%20Sep%2027,%202026,%2007_23_44%20AM.png'],['Gifts & Packaging','/shop/?collection=gift#collection','/gift/ChatGPT%20Image%20Sep%2027,%202026,%2007_23_36%20AM.png'],['Weddings','/wedding-events/','/wedding/ChatGPT%20Image%20Sep%2027,%202026,%2007_23_41%20AM.png'],['Hospitality','/hospitality/','/hospitality/Sultana%20Perfumes%20Executive%20Gift%20Collection.png'],['B2B & Corporate','/business-corporate/','/business-corporate/ChatGPT%20Image%20Sep%2027,%202026,%2007_23_18%20AM.png'],['Gift Voucher','/shop/?collection=gift-voucher#collection','/gift-voucher/ChatGPT%20Image%20Sep%2027,%202026,%2007_23_12%20AM.png'],['Our Story','/our-story/','/our-story/ChatGPT%20Image%20Sep%2027,%202026,%2007_23_07%20AM.png']];
  const buildVisualMenu=()=>{if(document.querySelector('.visual-home-menu'))return;document.body.classList.add('home-visual-nav');const hero=document.querySelector('.hero-carousel');if(!hero)return;const section=document.createElement('section');section.className='visual-home-menu';section.setAttribute('aria-label','Explore Sultana');section.innerHTML=`<div class="visual-home-menu-head"><p class="eyebrow">EXPLORE SULTANA</p><span>Discover our world</span></div><div class="visual-home-menu-grid">${menuItems.map(([title,href,img])=>`<a class="visual-menu-card" href="${href}"><img src="${img}" alt="" loading="lazy"><strong>${title}</strong></a>`).join('')}</div>`;hero.insertAdjacentElement('afterend',section)};
  const buildPerfumeCollections=()=>{const q=new URLSearchParams(location.search);if(q.get('collection')!=='perfume'||document.querySelector('#perfume-collection-banners'))return;const catalog=document.querySelector('#collection');if(!catalog)return;const ar=document.documentElement.lang==='ar'||location.pathname.startsWith('/ar/');const items=[['women','Women','للنساء','/assets/collection-notes/women-hd.webp'],['men','Men','للرجال','/assets/collection-notes/men-hd.webp'],['unisex','Unisex','للجنسين','/assets/collection-notes/unisex-hd.webp']];const s=document.createElement('section');s.id='perfume-collection-banners';s.className='section-shell perfume-collection-banners';s.innerHTML=`<div class="section-heading"><div><p class="eyebrow">${ar?'مجموعات العطور':'PERFUME COLLECTIONS'}</p><h1>${ar?'اكتشف مجموعتك.':'Find your collection.'}</h1></div></div><div class="perfume-collection-banner-grid">${items.map(([id,en,ara,img])=>`<a class="perfume-collection-banner" href="${ar?'/ar':''}/shop/?collection=${id}#collection"><img src="${img}" alt="${ar?ara:en}"><span>${ar?ara:en}</span></a>`).join('')}</div>`;catalog.parentNode.insertBefore(s,catalog)};
  const syncPrivateCollection=()=>{const g=document.querySelector('#bakhoor-products');if(!g||typeof products==='undefined'||typeof card!=='function')return;g.innerHTML=['sultana-oud','royal-bukhoor','amber-night','oud-collection-set'].map(id=>products.find(p=>p.id===id)).filter(Boolean).map(card).join('')};
  const syncHomeSprays=()=>{const g=document.querySelector('#home-products');if(!g)return;[...g.querySelectorAll('.product-card')].slice(4).forEach(e=>e.remove());g.querySelectorAll('.product-card').forEach(c=>{const t=(c.querySelector('h3')?.textContent||'').trim(),src=finalImages[t],img=c.querySelector('img');if(src&&img){img.src=src;img.removeAttribute('srcset')}})};
  const syncStoryHero=()=>{const img=document.querySelector('#hero-our-story img');if(!img)return;const mobile=window.matchMedia('(max-width:700px)').matches;img.src=mobile?'/assets/campaigns/hero-story-mobile.webp':'/assets/campaigns/hero-story-unified.webp';img.removeAttribute('srcset');};
  const apply=()=>{buildVisualMenu();buildPerfumeCollections();syncHomeSprays();syncPrivateCollection();syncStoryHero();const l=document.querySelector('#best-sellers .text-link');if(l){l.href=perfumeUrl;l.innerHTML='Explore more <span aria-hidden="true">↗</span>'}};
  const mq=window.matchMedia('(max-width:700px)');if(mq.addEventListener)mq.addEventListener('change',syncStoryHero);else mq.addListener(syncStoryHero);
  document.addEventListener('click',e=>{const l=e.target.closest('#best-sellers .text-link');if(!l)return;e.preventDefault();e.stopImmediatePropagation();location.href=perfumeUrl},true);if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',apply,{once:true});else apply();
})();
